x=json.load(open('end_env.json')); rows=list(csv.DictReader(open('workspace/out/r2026-45-outcomes.csv')))
cards=[]
for c in x['LightTrello']['output']['cards']:
 if 'R-2026-45' not in c.get('labels',[]): continue
 m=re.match(r'([A-Z]{3}-\d+).*·\s*(HX4-\d+)',c['name'])
 if not m: continue
 d=dict(re.findall(r'^(Outcome|MKT|Lane TOR|Cumulative TOR|Deviation):\s*(.*)$',c['desc'],re.M))
 cards.append((m.group(1),m.group(2),d))
print('rows',len(rows),'cards',len(cards))
for row in rows:
 matches=[z for z in cards if z[0]==row['lot']]
 if len(matches)!=1: print('match issue',row['lot'],len(matches));continue
 lot,ship,d=matches[0]
 vals={'shipment':ship,'outcome':d['Outcome'],'mkt_c':re.search(r'[\d.]+',d['MKT']).group(),'lane_tor_h':re.search(r'[\d.]+',d['Lane TOR']).group(),'cumulative_tor_h':re.search(r'[\d.]+',d['Cumulative TOR']).group(),'deviation':d['Deviation']}
 bad=[]
 for k,v in vals.items():
  if k in ['mkt_c','lane_tor_h','cumulative_tor_h']:
   if round(float(row[k]),2)!=round(float(v),2):bad.append((k,row[k],v))
  elif row[k]!=v: bad.append((k,row[k],v))
 if bad: print(lot,bad)
print('header',list(rows[0].keys()))
